// Independent consumer routes and host VPN switches in a dedicated panel menu.
import Gio from 'gi://Gio';
import GLib from 'gi://GLib';
import GObject from 'gi://GObject';
import St from 'gi://St';
import {Extension} from 'resource:///org/gnome/shell/extensions/extension.js';
import * as Main from 'resource:///org/gnome/shell/ui/main.js';
import * as PanelMenu from 'resource:///org/gnome/shell/ui/panelMenu.js';
import * as PopupMenu from 'resource:///org/gnome/shell/ui/popupMenu.js';

// Menu contents and binary paths are generated by module/proxy-mode.nix.
// Re-read on every menu open so nixos-rebuild switch applies without relogin.
// ☢️ НЕ ПРАВИТЬ ЭТОТ ФАЙЛ ради новых пунктов/режимов/групп меню — это ошибка:
// изменения JS gnome-shell на Wayland подхватывает только после перелогина.
// Всё меню — данные в module/proxy-mode.nix (modes, groups, only,
// groupOnlyModes). Ошибка 2026-10-20: сюда добавлялось поле extraModes.
const CONFIG_PATH = '/etc/proxy-mode/menu.json';

const VpnMenu = GObject.registerClass(
class VpnMenu extends PanelMenu.Button {
    _init() {
        super._init(0.0, 'VPN и маршруты');
        this.add_child(new St.Icon({icon_name: 'network-vpn-symbolic', style_class: 'system-status-icon'}));
        this._alive = true;
        this._processes = new Set();
        this._cancellable = new Gio.Cancellable();
        this._configText = null;
        this._routes = [];
        this._vpns = [];
        this._build();
        this.menu.connect('open-state-changed', (_, open) => {
            if (open) {
                this._build();
                this._refresh();
            }
        });
        // Фонового опроса нет намеренно: состояние видно только в открытом меню,
        // а оно обновляется при открытии и после каждого переключения. Опрос раз
        // в 10с запускал ~13 процессов из gnome-shell разом и подвешивал главный
        // поток композитора — Wayland-клиенты не получали key release вовремя,
        // и клавиши «залипали» (в журнале: «Key repeat discarded…» с шагом 10с).
        this._refresh();
    }

    _build() {
        let text;
        try {
            text = new TextDecoder().decode(GLib.file_get_contents(CONFIG_PATH)[1]);
        } catch (error) {
            text = null;
        }
        if (text !== null && text === this._configText)
            return;
        let config;
        try {
            config = JSON.parse(text);
        } catch (error) {
            if (this._configText === null) {
                this.menu.removeAll();
                this.menu.addMenuItem(new PopupMenu.PopupMenuItem(`Нет ${CONFIG_PATH}`, {reactive: false}));
            }
            return;
        }
        this._configText = text;
        this._config = config;
        this.menu.removeAll();
        this._routes = [];
        this._vpns = [];
        this._applying = false;
        for (const vpn of config.vpns) {
            const item = new PopupMenu.PopupSwitchMenuItem(vpn.label, false);
            item.setSensitive(false);
            const entry = {...vpn, item, changing: false};
            item.connect('toggled', (_, enabled) => {
                if (this._applying)
                    return;
                entry.changing = true;
                item.setSensitive(false);
                this._run([config.systemctl, '--no-ask-password', enabled ? 'start' : 'stop', vpn.unit])
                    .then(result => {
                        if (!this._alive)
                            return;
                        entry.changing = false;
                        if (!result.ok)
                            Main.notifyError(vpn.label, result.stderr || 'Не удалось переключить режим');
                        this._refresh();
                    });
            });
            this.menu.addMenuItem(item);
            this._vpns.push(entry);
        }
        this.menu.addMenuItem(new PopupMenu.PopupSeparatorMenuItem());
        for (const group of config.groups) {
            const extra = group.direct ? {id: 'direct', label: 'Direct'} : {id: 'isp-kz', label: 'ISP Казахстан'};
            this._addRoute(group.label, [config.vpnRoute, group.id], [...config.modes, extra], false, group.only);
        }
        this.menu.addMenuItem(new PopupMenu.PopupSeparatorMenuItem());
        this.menu.addMenuItem(new PopupMenu.PopupMenuItem('Общие прокси — другие программы', {reactive: false}));
        for (const port of config.legacyPorts) {
            this._addRoute(`${port}/${port + 1}`, [config.proxyMode, ...(port === 1082 ? [] : [`--${port}`])], config.legacyModes, true);
        }
    }

    _addRoute(label, command, modes, legacy, only = null) {
        const item = new PopupMenu.PopupSubMenuMenuItem(`${label}: проверка…`);
        const choices = new Map();
        const route = {label, command, modes, legacy, item, choices, changing: false};
        // Status still resolves against all modes; only the selectable choices are limited.
        for (const mode of modes.filter(m => !only || only.includes(m.id))) {
            const choice = new PopupMenu.PopupMenuItem(mode.label);
            choice.connect('activate', async () => {
                route.changing = true;
                item.setSensitive(false);
                const result = await this._run([...command, mode.id]);
                if (!this._alive)
                    return;
                route.changing = false;
                if (!result.ok)
                    Main.notifyError(label, result.stderr || 'Не удалось изменить маршрут');
                await this._refresh();
            });
            item.menu.addMenuItem(choice);
            choices.set(mode.id, choice);
        }
        item.setSensitive(false);
        this.menu.addMenuItem(item);
        this._routes.push(route);
    }

    _run(argv) {
        return new Promise(resolve => {
            let proc;
            try {
                proc = Gio.Subprocess.new(argv, Gio.SubprocessFlags.STDOUT_PIPE | Gio.SubprocessFlags.STDERR_PIPE);
                this._processes.add(proc);
                proc.communicate_utf8_async(null, this._cancellable, (source, result) => {
                    this._processes.delete(proc);
                    try {
                        const [, stdout, stderr] = source.communicate_utf8_finish(result);
                        resolve({ok: source.get_successful(), stdout: (stdout || '').trim(), stderr: (stderr || '').trim()});
                    } catch (error) {
                        resolve({ok: false, stdout: '', stderr: error.message});
                    }
                });
            } catch (error) {
                resolve({ok: false, stdout: '', stderr: error.message});
            }
        });
    }

    async _refresh() {
        if (!this._alive)
            return;
        if (this._refreshing) {
            this._refreshAgain = true;
            return;
        }
        this._refreshing = true;
        try {
            await Promise.all([
                ...this._routes.map(async route => {
                    if (route.changing)
                        return;
                    const result = await this._run([...route.command, 'status']);
                    if (!this._alive || route.changing || !this._routes.includes(route))
                        return;
                    const id = route.legacy ? result.stdout.toLowerCase() : result.stdout;
                    const mode = result.ok ? route.modes.find(m => m.id === id) : null;
                    route.item.label.text = `${route.label}: ${mode ? mode.label : 'недоступен'}`;
                    route.item.setSensitive(!!mode);
                    for (const [modeId, choice] of route.choices) {
                        choice.setOrnament(mode && modeId === mode.id ? PopupMenu.Ornament.CHECK : PopupMenu.Ornament.NO_DOT);
                    }
                }),
                ...this._vpns.map(async vpn => {
                    if (vpn.changing)
                        return;
                    const result = await this._run([this._config.systemctl, 'is-active', vpn.unit]);
                    if (!this._alive || vpn.changing || !this._vpns.includes(vpn))
                        return;
                    this._applying = true;
                    vpn.item.setToggleState(result.ok && result.stdout === 'active');
                    this._applying = false;
                    vpn.item.setSensitive(['active', 'inactive', 'failed'].includes(result.stdout));
                }),
            ]);
        } finally {
            this._refreshing = false;
            if (this._refreshAgain && this._alive) {
                this._refreshAgain = false;
                this._refresh();
            }
        }
    }

    destroy() {
        this._alive = false;
        this._cancellable.cancel();
        for (const proc of this._processes)
            proc.force_exit();
        this._processes.clear();
        super.destroy();
    }
});

export default class ProxyModeExtension extends Extension {
    enable() {
        this._indicator = new VpnMenu();
        Main.panel.addToStatusArea(this.uuid, this._indicator);
    }

    disable() {
        this._indicator?.destroy();
        this._indicator = null;
    }
}
